// Package geo is the backend administrative-division index (country → province →
// prefecture → county). It is generated by tools/codegen/geoindex.mjs from the same
// apps/web-console/public/geo/geo-manifest.json the browser loads and embedded at build
// time, so the production image needs no front-end file or URL at runtime.
//
// Version() is the SHA-256 of the source manifest bytes; the API returns it as
// scope.geoIndexVersion so a client can prove both sides use the same code table.
package geo

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"sync"
)

const Country = 100000

type Level string

const (
	LevelCountry    Level = "country"
	LevelProvince   Level = "province"
	LevelPrefecture Level = "prefecture"
	LevelCounty     Level = "county"
)

type Region struct {
	Code   int
	Parent int
	Level  Level
	Name   string
}

// Index is immutable after Parse.
type Index struct {
	version  string
	regions  map[int]Region
	children map[int][]int
}

var (
	ErrUnavailable = errors.New("administrative index unavailable")
	ErrNotFound    = errors.New("administrative region not found")
)

//go:embed index.gen.json
var embedded []byte

var (
	loadOnce sync.Once
	loaded   *Index
	loadErr  error
)

// Default returns the embedded index. A corrupt or missing embedded file yields
// ErrUnavailable (wrapped) — callers must answer 503, never fall back to "no region".
func Default() (*Index, error) {
	loadOnce.Do(func() { loaded, loadErr = Parse(embedded) })
	return loaded, loadErr
}

type file struct {
	Version string               `json:"version"`
	Source  string               `json:"source"`
	Regions [][4]json.RawMessage `json:"regions"`
}

var levels = map[string]Level{"C": LevelCountry, "P": LevelProvince, "M": LevelPrefecture, "X": LevelCounty}

// Parse validates the whole structure: unique codes, a single country root, every
// parent present, levels strictly deeper than their parent, and no cycles. Any
// violation makes the index unavailable rather than partially usable.
func Parse(b []byte) (*Index, error) {
	if len(b) == 0 {
		return nil, fmt.Errorf("%w: empty", ErrUnavailable)
	}
	var f file
	if err := json.Unmarshal(b, &f); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	if len(f.Version) != 64 || len(f.Regions) == 0 {
		return nil, fmt.Errorf("%w: missing version or regions", ErrUnavailable)
	}
	ix := &Index{version: f.Version, regions: map[int]Region{}, children: map[int][]int{}}
	for _, raw := range f.Regions {
		var r Region
		var level string
		if json.Unmarshal(raw[0], &r.Code) != nil || json.Unmarshal(raw[1], &r.Parent) != nil || json.Unmarshal(raw[2], &level) != nil || json.Unmarshal(raw[3], &r.Name) != nil {
			return nil, fmt.Errorf("%w: malformed region row", ErrUnavailable)
		}
		lv, ok := levels[level]
		if !ok || r.Code < 100000 || r.Code > 999999 || r.Name == "" {
			return nil, fmt.Errorf("%w: invalid region %d", ErrUnavailable, r.Code)
		}
		r.Level = lv
		if _, dup := ix.regions[r.Code]; dup {
			return nil, fmt.Errorf("%w: duplicate region %d", ErrUnavailable, r.Code)
		}
		ix.regions[r.Code] = r
	}
	root, ok := ix.regions[Country]
	if !ok || root.Level != LevelCountry || root.Parent != 0 {
		return nil, fmt.Errorf("%w: country root missing", ErrUnavailable)
	}
	depth := map[Level]int{LevelCountry: 0, LevelProvince: 1, LevelPrefecture: 2, LevelCounty: 3}
	for code, r := range ix.regions {
		if code == Country {
			continue
		}
		p, ok := ix.regions[r.Parent]
		if !ok || depth[p.Level] >= depth[r.Level] {
			return nil, fmt.Errorf("%w: region %d has invalid parent %d", ErrUnavailable, code, r.Parent)
		}
		ix.children[r.Parent] = append(ix.children[r.Parent], code)
	}
	for _, c := range ix.children {
		sort.Ints(c)
	}
	return ix, nil
}

func (ix *Index) Version() string { return ix.version }

func (ix *Index) Region(code int) (Region, bool) {
	r, ok := ix.regions[code]
	return r, ok
}

// Children returns the direct sub-regions of code, sorted.
func (ix *Index) Children(code int) []Region {
	out := make([]Region, 0, len(ix.children[code]))
	for _, c := range ix.children[code] {
		out = append(out, ix.regions[c])
	}
	return out
}

// Descendants returns code itself and every region below it (sorted). For the country it
// returns every region. Unknown code → ErrNotFound.
func (ix *Index) Descendants(code int) ([]int, error) {
	if _, ok := ix.regions[code]; !ok {
		return nil, ErrNotFound
	}
	out := []int{}
	stack := []int{code}
	for len(stack) > 0 {
		c := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		out = append(out, c)
		stack = append(stack, ix.children[c]...)
	}
	sort.Ints(out)
	return out, nil
}

// ChildOf returns which direct child of `scope` contains `code` (code itself if it is a
// direct child). ok=false when code is not strictly below scope, or is scope itself.
// A code unknown to the index never matches anything.
func (ix *Index) ChildOf(scope, code int) (int, bool) {
	cur, ok := ix.regions[code]
	if !ok {
		return 0, false
	}
	for cur.Code != Country {
		if cur.Parent == scope {
			return cur.Code, true
		}
		cur, ok = ix.regions[cur.Parent]
		if !ok {
			return 0, false
		}
	}
	return 0, false
}
